<script setup lang="ts">
import {computed} from 'vue';const props=defineProps<{network:any;placement:{wind_node:number;pv_node:number};snapshot?:any;failedLines?:number[];editable?:boolean;selectedNode?:number;selectedLine?:number}>();
function nodeDetail(id:number){return props.snapshot?.nodes.find((n:any)=>n.node===id)}
function lineDetail(id:number){return props.snapshot?.lines.find((l:any)=>l.line===id)}
function nodeColor(id:number){const detail=nodeDetail(id);if(detail&&!detail.connected)return '#a5adb1';if(detail&&detail.served_kw<detail.load_kw-1e-6)return '#c98329';return [1,props.placement.wind_node,props.placement.pv_node].includes(id)?'#087b7b':'#e0eeee'}
const emit=defineEmits<{toggleLine:[id:number];selectNode:[id:number];selectLine:[id:number];inspectNode:[id:number];inspectLine:[id:number]}>();
const positions=computed(()=>{const depth:Record<number,number>={1:0};const counts:Record<number,number>={};const points:Record<number,{x:number;y:number}>={};const queue=[1];for(const id of queue)for(const l of props.network.lines.filter((l:any)=>l.status===1)){const next=l.from_node===id?l.to_node:l.to_node===id?l.from_node:null;if(next!==null&&depth[next]===undefined){depth[next]=depth[id]+1;queue.push(next)}}for(const n of props.network.nodes){const d=depth[n.node]??0;const row=counts[d]||0;counts[d]=row+1;points[n.node]={x:45+95*d,y:45+80*row}}return points});
const viewBox=computed(()=>{const p=Object.values(positions.value);return `0 0 ${Math.max(500,...p.map(v=>v.x+50))} ${Math.max(260,...p.map(v=>v.y+60))}`});
function failed(id:number){return props.failedLines?.includes(id)||lineDetail(id)?.failed}
</script>
<template><div class="topology"><svg :viewBox="viewBox" preserveAspectRatio="xMinYMin meet" role="img" aria-label="当前电网拓扑"><g v-for="l in network.lines.filter((l:any)=>l.status===1)" :key="l.line" :style="{cursor:editable?'pointer':'default'}" role="button" :tabindex="editable?0:undefined" :aria-label="'线路'+l.line+(failed(l.line)?'故障':'正常')" @dblclick.stop="!editable&&emit('inspectLine',l.line)" @click="editable?emit('toggleLine',l.line):emit('selectLine',l.line)" @keydown.enter.prevent="editable&&emit('toggleLine',l.line)" @keydown.space.prevent="editable&&emit('toggleLine',l.line)"><line :x1="positions[l.from_node].x" :y1="positions[l.from_node].y" :x2="positions[l.to_node].x" :y2="positions[l.to_node].y" stroke="transparent" stroke-width="18"/><line :x1="positions[l.from_node].x" :y1="positions[l.from_node].y" :x2="positions[l.to_node].x" :y2="positions[l.to_node].y"  :stroke="selectedLine===l.line?'#1764d8':failed(l.line)?'#bd3e3e':'#40566c'" :stroke-dasharray="failed(l.line)?'7 4':undefined" stroke-width="3"/><rect :x="(positions[l.from_node].x+positions[l.to_node].x)/2-14" :y="(positions[l.from_node].y+positions[l.to_node].y)/2-10" width="28" height="20" rx="4" fill="#f8fbfb"/><text :x="(positions[l.from_node].x+positions[l.to_node].x)/2" :y="(positions[l.from_node].y+positions[l.to_node].y)/2+4" text-anchor="middle" font-size="11" :fill="failed(l.line)?'#bd3e3e':'#235057'">{{l.line}}</text><title>线路{{l.line}}{{lineDetail(l.line)?' · 线性有功潮流 '+lineDetail(l.line).flow_kw.toFixed(2)+' kW'+(lineDetail(l.line).failed?' · 故障':''):''}}</title></g><g v-for="n in network.nodes" :key="n.node" style="cursor:pointer" @dblclick.stop="emit('inspectNode',n.node)" @click="emit('selectNode',n.node)"><circle :cx="positions[n.node].x" :cy="positions[n.node].y" r="15" :fill="nodeColor(n.node)" :stroke="selectedNode===n.node?'#1764d8':'#40566c'" :stroke-width="selectedNode===n.node?4:1.5"/><title>节点{{n.node}}{{nodeDetail(n.node)?' · 供电 '+nodeDetail(n.node).served_kw.toFixed(2)+' / '+nodeDetail(n.node).load_kw.toFixed(2)+' kW · '+(nodeDetail(n.node).connected?'根节点连通':'与根节点失联'):''}}</title><text :x="positions[n.node].x" :y="positions[n.node].y+4" text-anchor="middle" :fill="[1,placement.wind_node,placement.pv_node].includes(n.node)?'white':'#235057'" font-size="12">{{n.node}}</text></g></svg></div><p>示意布局，非地理坐标。1号为根节点，{{placement.wind_node}}号风电、{{placement.pv_node}}号光伏，线路依据当前已应用网络绘制。</p></template>
<style scoped>.topology{overflow:auto;background:#f8fbfb}.topology svg{min-width:1000px;width:100%;max-height:480px}</style>
